sealed class Outcome161 {
    data class Success(val payload: String) : Outcome161()
    data object Failure : Outcome161()
}

fun describe161(outcome: Outcome161): String = when (outcome) {
    is Outcome161.Success -> outcome.payload
    Outcome161.Failure -> "failed"
}
